yaml_query() {
  python3 - "$WORKFLOW" <<PYEOF
import sys, yaml
with open(sys.argv[1]) as fh:
    wf = yaml.safe_load(fh)
on_ = wf.get('on', wf.get(True))
assert $1, "assertion failed: $1"
PYEOF
}

